return ['domain'=>'zinn-cache','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'mn','project-id-version'=>'zinn-cache','pot-creation-date'=>'2026-09-02T07:33:02+00:00','po-revision-date'=>'2026-09-02T07:33:02+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache'=>'Zinn® Cache','https://zinndigital.com/wordpress-plugins/zinn-cache'=>'https://zinndigital.com/wordpress-plugins/zinn-cache','For sites hosted with Zinn Digital®. Controls the page cache your Zinn® server already provides — smart auto-purge on content change, remote purge from your Zinn® dashboard, a Redis object-cache toggle, safe WordPress/WooCommerce exclusions, and one-click admin login. This is a cache controller, not a cache engine. Hosting elsewhere? Install Zinn® Cache Engine instead.'=>'Zinn Digital® дээр байршуулсан сайтуудад зориулагдсан. Таны Zinn® серверийн аль хэдийн хангадаг хуудасны кэшийг удирдана — контент өөрчлөгдөхөд автоматаар ухаалаг цэвэрлэх, Zinn® хяналтын самбараас алсаас цэвэрлэх, Redis объектын кэшийг асаах/унтраах товчлуур, WordPress/WooCommerce-ийн аюулгүй хасалтууд, нэг товшилтоор админаар нэвтрэх боломж. Энэ бол кэш хянагч бөгөөд кэш хөдөлгүүр биш юм. Өөр газар байршуулж байна уу? Үүний оронд Zinn® Cache Engine суулгана уу.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','You are not allowed to purge the cache.'=>'Танд кэшийг цэвэрлэх зөвшөөрөл байхгүй.','Cache purge requested.'=>'Кэш цэвэрлэх хүсэлт гаргалаа.','Zinn® Cache: another object-cache drop-in is installed, so the Redis object cache is not managed by this plugin.'=>'Zinn® Cache: өөр объект кеш залгаас суулгасан байгаа тул Redis объект кешийг энэ плагинаар удирдахгүй.','Full-page cache (LiteSpeed)'=>'Бүрэн хуудасны кэш (LiteSpeed)','Enable LSCache control'=>'LSCache удирдлагыг идэвхжүүлэх','Send LiteSpeed cache-control and tag headers on cacheable pages.'=>'Кэшлэгдэх боломжтой хуудсууд дээр LiteSpeed кэш удирдлага болон тэгийн толгойнуудыг илгээх.','Public cache lifetime (seconds)'=>'Нийтийн кэшийн хугацаа (секунд)','Object cache (Redis)'=>'Объект кэш (Redis)','Enable Redis object cache'=>'Redis объект кэшийг идэвхжүүлэх','Install the Redis object-cache drop-in (requires the phpredis extension).'=>'Redis объект кэшийн drop-in суулгах (phpredis өргөтгөл шаардлагатай).','Redis host'=>'Redis хост','Redis port'=>'Redis порт','Redis database'=>'Redis өгөгдлийн сан','Redis key prefix'=>'Redis түлхүүрийн угтвар','Automatic purging'=>'Автомат цэвэрлэгээ','Smart auto-purge'=>'Ухаалаг автомат цэвэрлэгээ','Purge affected pages automatically when content changes.'=>'Контент өөрчлөгдөх үед холбогдох хуудсуудыг автоматаар цэвэрлэх.','Purge on updates'=>'Шинэчлэлт хийх үед цэвэрлэх','Purge everything after core, plugin, or theme updates.'=>'Гол систем, нэмэлт болон загварыг шинэчилсний дараа бүгдийг цэвэрлэх.','Cache exclusions'=>'Кэшээс хасалт','Sensible WordPress and WooCommerce defaults are always applied (cart, checkout, my-account, logged-in and session pages are never cached). Add extra rules below, one per line.'=>'WordPress болон WooCommerce-ийн боломжийн анхны тохиргоо үргэлж хэрэглэгддэг (сагс, төлбөр төлөлт, миний бүртгэл, нэвтэрсэн болон сешн хуудсууд хэзээ ч кэшлэгдэхгүй). Доор нэмэлт дүрмийг мөр тус бүрт нэгээр нэмнэ үү.','Exclude URL paths (prefix match)'=>'Хасах URL зам (угтвар тохирол)','Exclude query keys'=>'Хасах query түлхүүрүүд','Exclude cookie name prefixes'=>'Хасах күүкигийн нэрийн угтварууд','Maintenance'=>'Засвар үйлчилгээ','Purge everything now'=>'Одоо бүгдийг цэвэрлэх','detected'=>'илрүүлсэн','not detected'=>'илрүүлээгүй','phpredis extension missing'=>'phpredis өргөтгөл байхгүй','active'=>'идэвхтэй','inactive'=>'идэвхгүй','LiteSpeed cache:'=>'LiteSpeed кэш:','Redis object cache:'=>'Redis объект кэш:','The Redis PHP extension (phpredis) is not available on this server, so the object cache cannot be enabled.'=>'Энэ серверт Redis PHP өргөтгөл (phpredis) 